private static int decodeOctets(int i, java.nio.ByteBuffer bb, java.lang.StringBuilder sb) {
    int startPos = bb.position();
    java.nio.charset.CharsetDecoder decoder = java.nio.charset.StandardCharsets.UTF_8.newDecoder();
    try {
        java.nio.CharBuffer cb = decoder.decode(bb);
        sb.append(cb);
    } catch (java.nio.charset.CharacterCodingException e) {
        // Fallback: append each byte as a character
        bb.position(startPos);
        while (bb.hasRemaining()) {
            int b = bb.get() & 0xFF;
            sb.append((char) b);
        }
    }
    int consumed = bb.position() - startPos;
    return i + consumed;
}

private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb){
    int b1 = bb.get() & 0xFF;
    int bytesDecoded;
    if ((b1 & 0x80) == 0){ // 1-byte ASCII
        sb.append((char)b1);
        bytesDecoded = 1;
    } else if ((b1 & 0xE0) == 0xC0){ // 2-byte sequence
        int b2 = bb.get() & 0xFF;
        int cp = ((b1 & 0x1F) << 6) | (b2 & 0x3F);
        sb.append((char)cp);
        bytesDecoded = 2;
    } else if ((b1 & 0xF0) == 0xE0){ // 3-byte sequence
        int b2 = bb.get() & 0xFF;
        int b3 = bb.get() & 0xFF;
        int cp = ((b1 & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
        sb.append((char)cp);
        bytesDecoded = 3;
    } else if ((b1 & 0xF8) == 0xF0){ // 4-byte sequence
        int b2 = bb.get() & 0xFF;
        int b3 = bb.get() & 0xFF;
        int b4 = bb.get() & 0xFF;
        int cp = ((b1 & 0x07) << 18) | ((b2 & 0x3F) << 12) |
                 ((b3 & 0x3F) << 6) | (b4 & 0x3F);
        cp -= 0x10000;
        char high = (char)((cp >> 10) + 0xD800);
        char low  = (char)((cp & 0x3FF) + 0xDC00);
        sb.append(high).append(low);
        bytesDecoded = 4;
    } else { // malformed byte, use replacement character
        sb.append('\uFFFD');
        bytesDecoded = 1;
    }
    return i + bytesDecoded;
}

