            if (bb.remaining() < 2) break; // incomplete
            int b1 = bb.get() & 0xFF;
            int b2 = bb.get() & 0xFF;
            int codePoint = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
            sb.append((char) codePoint);
        } else if ((b0 & 0xF8) == 0xF0) { // four-byte sequence (surrogate pair)
            if (bb.remaining() < 3) break; // incomplete
            int b1 = bb.get() & 0xFF;
            int b2 = bb.get() & 0xFF;
