    int b0 = bb.get(i) & 0xFF;
    if ((b0 & 0x80) == 0) { // 1 byte
        sb.append((char) b0);
        return i + 1;
    }
    if ((b0 & 0xE0) == 0xC0) { // 2 bytes
        int b1 = bb.get(i + 1) & 0x3F;
        int ch = ((b0 & 0x1F) << 6) | b1;
        sb.append((char) ch);
        return i + 2;
    }
    if ((b0 & 0xF0) == 0xE0) { // 3 bytes
        int b1 = bb.get(i + 1) & 0x3F;
        int b2 = bb.get(i + 2) & 0x3F;
        int ch = ((b0 & 0x0F) << 12) | (b1 << 6) | b2;
        sb.append((char) ch);
        return i + 3;
    }
    // 4 bytes
    int b1 = bb.get(i + 1) & 0x3F;
    int b2 = bb.get(i + 2) & 0x3F;
    int b3 = bb.get(i + 3) & 0x3F;
    int codePoint = ((b0 & 0x07) << 18) | (b1 << 12) | (b2 << 6) | b3;
