public static void addToClassPath(Vector<URL> cpV, String dir) {
    File d = new File(dir);
    if (!d.isDirectory()) {
        return;
    }
    File[] jarFiles = d.listFiles(new FileFilter() {
        @Override
        public boolean accept(File f) {
            String n = f.getName();
            return f.isFile() && (n.endsWith(".jar") || n.endsWith(".JAR"));
        }
    });
    if (jarFiles == null) {
        return;
    }
    for (File jar : jarFiles) {
        try {
            cpV.add(jar.toURI().toURL());
        } catch (MalformedURLException e) {
            // If the URL cannot be formed, skip this jar
            e.printStackTrace();
        }
    }
}

@SuppressWarnings("unchecked")
public static void addToClassPath(Vector<URL> cpV,String dir){
    if (cpV == null || dir == null) {
        return;
    }
    File folder = new File(dir);
    if (!folder.isDirectory()) {
        return;
    }
    File[] files = folder.listFiles();
    if (files == null) {
        return;
    }
    for (File f : files) {
        if (f.isFile() && f.getName().toLowerCase(Locale.ROOT).endsWith(".jar")) {
            try {
                cpV.add(f.toURI().toURL());
            } catch (MalformedURLException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

