public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Collect all vertices present in the target graph
    Collection<V> vertsCollection;
    try {
        vertsCollection = target.getVertices(); // or target.vertexSet() if needed
    } catch (Exception e) {
        // If the graph library does not provide getVertices, abort
        return;
    }

    List<V> verts = new ArrayList<>(vertsCollection);
    int count = verts.size();
    if (count < 2) return; // cannot form a bipartite graph with fewer than two vertices

    // Divide the vertices into two parts, alternating
    List<V> partA = new ArrayList<>();
    List<V> partB = new ArrayList<>();
    for (int i = 0; i < count; i++) {
        if (i % 2 == 0) {
            partA.add(verts.get(i));
        } else {
            partB.add(verts.get(i));
        }
    }

    // Record each vertex in the result map with a simple key
    int idx = 0;
    for (V v : verts) {
        resultMap.put("v" + idx, v);
        idx++;
    }

    // Add edges between every pair of vertices from opposite parts to create a
    // complete bipartite graph. Skip an edge if it already exists.
    for (V u : partA) {
        for (V v : partB) {
            E existing = null;
            try {
                existing = target.getEdge(u, v);
            } catch (Exception ignored) {
                // Method may not exist; ignore
            }
            if (existing == null) {
                target.addEdge(u, v);
            }
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    // If target graph already has vertices, we assume we should populate it
    // Build a bipartite graph from the vertices in resultMap.
    // Split the vertices into two sets: first half as left, second half as right.
    List<V> vertices = new ArrayList<>(resultMap.values());
    int total = vertices.size();
    if(total == 0) return;
    int mid = total / 2;
    // If odd number, left gets the extra vertex
    List<V> left = vertices.subList(0, mid + (total % 2));
    List<V> right = vertices.subList(left.size(), total);
    // Add all vertices to the target graph
    for(V v: vertices) {
        target.addVertex(v);
    }
    // Add all edges between left and right (complete bipartite)
    for(V u: left){
        for(V v: right){
            target.addEdge(u, v);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    for (Map.Entry<String,V> entry : resultMap.entrySet()){
        String key = entry.getKey();
        if (key != null){
            if (key.startsWith("L")) left.add(entry.getValue());
            else if (key.startsWith("R")) right.add(entry.getValue());
        }
    }
    for (V u : left){
        for (V v : right){
            target.addEdge(u, v);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap) {
    int n = resultMap.size();
    if (n < 2) return;
    java.util.List<V> vertices = new java.util.ArrayList<>(resultMap.values());
    int mid = n / 2;
    // Add vertices to the graph
    for (V v : vertices) {
        target.addVertex(v);
    }
    // Create a complete bipartite structure between two halves
    for (int i = 0; i < mid; i++) {
        V left = vertices.get(i);
        for (int j = mid; j < n; j++) {
            V right = vertices.get(j);
            target.addEdge(left, right);
        }
    }
}

