public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    buffer.clear();  // reset the buffer for reuse
    // Encode the message into the buffer
    schema.write(message, buffer);
    int size = buffer.getSize();
    // Write the length prefix (32‑bit big‑endian)
    out.write((size >>> 24) & 0xFF);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 8) & 0xFF);
    out.write(size & 0xFF);
    // Write the serialized message
    out.write(buffer.getArray(), 0, size);
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    int size = schema.getSerializedSize(message, buffer);
    cos.writeRawVarint32(size);
    schema.writeTo(message, cos, buffer);
    cos.flush();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Get the serialized size of the message using the provided schema and buffer.
    int size = schema.getSerializedSize(message, buffer);

    // Write the size as a varint32 prefix to the output stream.
    int len = size;
    while ((len & ~0x7F) != 0) {
        out.write((len & 0x7F) | 0x80);
        len >>>= 7;
    }
    out.write(len);

    // Serialize the actual message to the same output stream using the schema.
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    schema.writeTo(cos, message);
    cos.flush();

    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Encode the message into a byte array using the provided LinkedBuffer
    byte[] serialized = schema.toByteArray(message, buffer);
    int size = serialized.length;

    // Prefix the serialized data with its size (4-byte big-endian)
    out.write((byte) (size >>> 24));
    out.write((byte) (size >>> 16));
    out.write((byte) (size >>> 8));
    out.write((byte) size);

    // Write the serialized message itself
    out.write(serialized);

    return size;
}

