public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pType = (ParameterizedType) genericType;
    Class<?> rawType = (Class<?>) pType.getRawType();
    Map<TypeVariable<?>, Type> typeVarMap = new HashMap<>();
    // Build a map of type variables from rawType to actual types as seen in targetType
    if (!buildTypeVariableMap(targetType, rawType, typeVarMap)) {
        return null;
    }
    Type[] actualArgs = pType.getActualTypeArguments();
    Class<?>[] resolved = new Class<?>[actualArgs.length];
    for (int i = 0; i < actualArgs.length; i++) {
        Class<?> cls = resolveClass(actualArgs[i], typeVarMap);
        if (cls == null) { // unresolved
            return null;
        }
        resolved[i] = cls;
    }
    return resolved;
}

/* Build a mapping of rawType's type variables to the actual types as they appear in targetType.
 * Returns true if a mapping could be established, false otherwise. */
private static boolean buildTypeVariableMap(Class<?> current, Class<?> raw, Map<TypeVariable<?>, Type> map) {
    if (current == null) {
        return false;
    }
    // Check superclass
    Type superType = current.getGenericSuperclass();
    if (superType instanceof ParameterizedType) {
        ParameterizedType pt = (ParameterizedType) superType;
        Class<?> rawSuper = (Class<?>) pt.getRawType();
        if (rawSuper == raw) {
            TypeVariable<?>[] vars = raw.getTypeParameters();
            Type[] actuals = pt.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                map.put(vars[i], actuals[i]);
            }
            return true;
        }
    } else if (superType instanceof Class && superType == raw) {
        return true;
    }
    // Check interfaces
    for (Type iface : current.getGenericInterfaces()) {
        if (iface instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) iface;
            Class<?> rawIface = (Class<?>) pt.getRawType();
            if (rawIface == raw) {
                TypeVariable<?>[] vars = raw.getTypeParameters();
                Type[] actuals = pt.getActualTypeArguments();
                for (int i = 0; i < vars.length; i++) {
                    map.put(vars[i], actuals[i]);
                }
                return true;
            }
        } else if (iface instanceof Class && iface == raw) {
            return true;
        }
    }
    // Recurse into superclass
    if (buildTypeVariableMap(current.getSuperclass(), raw, map)) {
        return true;
    }
    // Recurse into interfaces
    for (Class<?> iface : current.getInterfaces()) {
        if (buildTypeVariableMap(iface, raw, map)) {
            return true;
        }
    }
    return false;
}

/* Resolve a Type to a Class using the provided type variable map. Returns null if it cannot be resolved. */
private static Class<?> resolveClass(Type type, Map<TypeVariable<?>, Type> map) {
    if (type instanceof Class) {
        return (Class<?>) type;
    }
    if (type instanceof TypeVariable) {
        TypeVariable<?> tv = (TypeVariable<?>) type;
        Type resolved = map.get(tv);
        if (resolved == null) {
            // Try bounds
            Type[] bounds = tv.getBounds();
            if (bounds.length > 0) {
                return resolveClass(bounds[0], map);
            }
            return null;
        }
        return resolveClass(resolved, map);
    }
    if (type instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) type).getRawType();
    }
    if (type instanceof GenericArrayType) {
        Type comp = ((GenericArrayType) type).getGenericComponentType();
        Class<?> compClass = resolveClass(comp, map);
        if (compClass == null) {
            return null;
        }
        return Array.newInstance(compClass, 0).getClass();
    }
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Class<?>[] result = new Class<?>[pt.getActualTypeArguments().length];
    Map<TypeVariable<?>, Type> typeVarMap = buildTypeVariableMap(targetType);
    for (int i = 0; i < pt.getActualTypeArguments().length; i++) {
        Type t = pt.getActualTypeArguments()[i];
        Class<?> c = resolveClass(t, typeVarMap);
        if (c == null) {
            return null;
        }
        result[i] = c;
    }
    return result;
}

private static Class<?> resolveClass(Type t, Map<TypeVariable<?>, Type> typeVarMap) {
    if (t instanceof Class<?>) {
        return (Class<?>) t;
    }
    if (t instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) t).getRawType();
    }
    if (t instanceof WildcardType) {
        WildcardType wt = (WildcardType) t;
        Type[] upper = wt.getUpperBounds();
        return upper.length > 0 ? resolveClass(upper[0], typeVarMap) : null;
    }
    if (t instanceof TypeVariable) {
        Type resolved = typeVarMap.get(t);
        if (resolved == null) {
            return null;
        }
        return resolveClass(resolved, typeVarMap);
    }
    return null;
}

private static Map<TypeVariable<?>, Type> buildTypeVariableMap(Class<?> cls) {
    Map<TypeVariable<?>, Type> result = new java.util.HashMap<>();
    Class<?> current = cls;
    while (current != null) {
        Type genericSuperclass = current.getGenericSuperclass();
        if (genericSuperclass instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) genericSuperclass;
            Class<?> raw = (Class<?>) pt.getRawType();
            TypeVariable<?>[] vars = raw.getTypeParameters();
            Type[] args = pt.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                result.put(vars[i], args[i]);
            }
            current = raw;
        } else {
            current = current.getSuperclass();
        }
    }
    return result;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        Class<?> resolved = resolveRawClass(args[i], targetType);
        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }
    return result;
}

private static Class<?> resolveRawClass(Type type, Class<?> targetType) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    }
    if (type instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) type).getRawType();
    }
    if (type instanceof WildcardType) {
        WildcardType wc = (WildcardType) type;
        Type[] upper = wc.getUpperBounds();
        if (upper.length > 0) {
            return resolveRawClass(upper[0], targetType);
        }
        return Object.class; // default upper bound
    }
    if (type instanceof TypeVariable<?>) {
        String name = ((TypeVariable<?>) type).getName();
        // Search in targetType's generic interfaces
        Type[] interfaces = targetType.getGenericInterfaces();
        for (Type iface : interfaces) {
            if (iface instanceof ParameterizedType) {
                ParameterizedType pIface = (ParameterizedType) iface;
                Class<?> rawIface = (Class<?>) pIface.getRawType();
                TypeVariable<?>[] vars = rawIface.getTypeParameters();
                for (int j = 0; j < vars.length; j++) {
                    if (vars[j].getName().equals(name)) {
                        Type actual = pIface.getActualTypeArguments()[j];
                        return resolveRawClass(actual, targetType);
                    }
                }
            }
        }
        // Search in superclass
        Type superType = targetType.getGenericSuperclass();
        if (superType instanceof ParameterizedType) {
            ParameterizedType pSuper = (ParameterizedType) superType;
            Class<?> rawSuper = (Class<?>) pSuper.getRawType();
            TypeVariable<?>[] vars = rawSuper.getTypeParameters();
            for (int j = 0; j < vars.length; j++) {
                if (vars[j].getName().equals(name)) {
                    Type actual = pSuper.getActualTypeArguments()[j];
                    return resolveRawClass(actual, targetType);
                }
            }
        }
        // Unable to resolve variable
        return null;
    }
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType paramGeneric = (ParameterizedType) genericType;
    Type rawType = paramGeneric.getRawType();
    if (!(rawType instanceof Class<?>)) {
        return null;
    }
    Class<?> rawClass = (Class<?>) rawType;

    // Find the type that matches rawClass in targetType's hierarchy
    Type found = findMatchingParameterizedType(targetType, rawClass);
    if (!(found instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType matched = (ParameterizedType) found;

    // Build map from rawClass's type variables to the matched type arguments
    TypeVariable<?>[] vars = rawClass.getTypeParameters();
    Type[] actualArgs = matched.getActualTypeArguments();
    if (vars.length != actualArgs.length) {
        return null;
    }
    java.util.Map<TypeVariable<?>, Type> varMap = new java.util.HashMap<>();
    for (int i = 0; i < vars.length; i++) {
        varMap.put(vars[i], actualArgs[i]);
    }

    // Resolve each argument of the original genericType
    Type[] originalArgs = paramGeneric.getActualTypeArguments();
    Class<?>[] result = new Class<?>[originalArgs.length];
    for (int i = 0; i < originalArgs.length; i++) {
        Type resolved = resolveTypeArgument(originalArgs[i], varMap);
        Class<?> clazz = extractClass(resolved);
        if (clazz == null) {
            return null;
        }
        result[i] = clazz;
    }
    return result;
}

// Helper to locate the ParameterizedType matching rawClass in targetType's ancestry
private static Type findMatchingParameterizedType(Class<?> cls, Class<?> rawClass) {
    if (cls == null) {
        return null;
    }
    // Check current class/interfaces
    if (cls.equals(rawClass)) {
        return cls;
    }
    // Interfaces
    for (Type intf : cls.getGenericInterfaces()) {
        if (intf instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) intf;
            if (pt.getRawType() instanceof Class<?> && ((Class<?>) pt.getRawType()).equals(rawClass)) {
                return pt;
            }
        }
        if (intf instanceof Class<?>) {
            Type t = findMatchingParameterizedType((Class<?>) intf, rawClass);
            if (t != null) {
                return t;
            }
        }
    }

