protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long current = start;
    while (current < end) {
        long segmentEnd = Math.min(end, current + FETCH_DATA_DURATION);
        ranges.add(new TimeRange(current, segmentEnd));
        current = segmentEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    java.util.List<TimeRange> ranges = new java.util.ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long nextStart = start;
    while (nextStart < end) {
        long nextEnd = Math.min(nextStart + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(nextStart, nextEnd));
        nextStart = nextEnd;
    }
    return ranges;
}

