}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long step = FETCH_DATA_DURATION;
    for (long s = start; s < end; s += step) {
        long e = Math.min(s + step, end);
        ranges.add(new TimeRange(s, e));
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (FETCH_DATA_DURATION <= 0) {
        return ranges;
    }
    long curStart = start;
    while (curStart <= end) {
        long curEnd = Math.min(end, curStart + FETCH_DATA_DURATION - 1L);
        ranges.add(new TimeRange(curStart, curEnd));
        curStart = curEnd + 1L;
    }
    return ranges;
}

