                    utf8Len += 4;
                    i++; // Skip the low surrogate
                } else {
                    utf8Len += 3; // Unpaired high surrogate
                }
            } else if (Character.isLowSurrogate(ch)) {
                utf8Len += 3; // Unpaired low surrogate
            } else {
                utf8Len += 3; // BMP character > 0x7FF
            }
        }
    }
    return utf8Len;
}

