}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }
    try {
        byte[] utf8 = str.toString().getBytes("UTF-8");
        if (lb != null) {
            if (session != null) {
                session.record(utf8.length);  // optional encoding bookkeeping
            }
            lb.write(utf8, 0, utf8.length);
        }
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Convert the provided CharSequence to a UTF‑8 encoded byte array
    byte[] utf8Bytes = str.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
    // Write each byte into the provided LinkedBuffer
    for (int i = 0; i < utf8Bytes.length; i++) {
        lb.write(utf8Bytes[i]);
    }
    // Return the modified buffer for chaining
    return lb;
}

