        path = path.substring(1);
    }
    String[] parts = path.split("/", -1); // keep trailing empty segments
    for (String part : parts) {
        String value = part;
        if (decode) {
            try {
                value = URLDecoder.decode(part, StandardCharsets.UTF_8.name());
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

public static java.util.List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    java.util.List<PathSegmentImpl> result = new java.util.ArrayList<>();
    if (u == null) {
        return result;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return result;
    }
    int start = 0;
    if (rawPath.startsWith("/")) {
        start = 1;
    }
    String path = rawPath.substring(start);
    String[] parts = path.split("/", -1); // preserve trailing empty segment
    for (String part : parts) {
        String seg = part;
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        result.add(new PathSegmentImpl(seg));
    }
    return result;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new ArrayList<>();
    if (u == null) {
        return result;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return result;
    }
    String[] parts = rawPath.split("/");
    int startIndex = 0;
    if (rawPath.startsWith("/")) {
        startIndex = 1;
    }
    for (int i = startIndex; i < parts.length; i++) {
        String seg = parts[i];
        if (seg.isEmpty()) {
            continue;
        }
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(seg, "UTF-8");
            } catch (Exception ignored) {
                // leave segment untouched if decoding fails
            }
        }
        result.add(new PathSegmentImpl(seg, decode));
    }
    return result;
}

