private void pop(final String descriptor){
    int i = 0;
    int len = descriptor.length();
    // If descriptor is a method descriptor, process only the argument types
    if(len > 0 && descriptor.charAt(0) == '('){
        i = 1;
        int end = descriptor.indexOf(')', i);
        if(end == -1) end = len;
        while(i < end){
            char c = descriptor.charAt(i);
            if(c == '['){
                // Skip one or more '[' characters
                do{ i++; }while(i < end && descriptor.charAt(i) == '[');
                // If array is of an object type, skip until ';'
                if(i < end && descriptor.charAt(i) == 'L'){
                    do{ i++; }while(i < end && descriptor.charAt(i) != ';');
                }
                pos--; // array type occupies one stack slot
            }else if(c == 'L'){
                // Object type: skip until ';'
                do{ i++; }while(i < end && descriptor.charAt(i) != ';');
                pos--; // object type occupies one stack slot
            }else{
                // Primitive type
                if(c == 'J' || c == 'D'){
                    pos -= 2; // long and double occupy two slots
                }else{
                    pos--;   // all other primitives occupy one slot
                }
            }
            i++;
        }
    }else{
        // Field or simple type descriptor
        while(i < len){
            char c = descriptor.charAt(i);
            if(c == '['){
                do{ i++; }while(i < len && descriptor.charAt(i) == '[');
                if(i < len && descriptor.charAt(i) == 'L'){
                    do{ i++; }while(i < len && descriptor.charAt(i) != ';');
                }
                pos--;
            }else if(c == 'L'){
                do{ i++; }while(i < len && descriptor.charAt(i) != ';');
                pos--;
            }else{
                if(c == 'J' || c == 'D'){
                    pos -= 2;
                }else{
                    pos--;
                }
            }
            i++;
        }
    }
}

private void pop(final String descriptor){
    if (descriptor.startsWith("(")) {
        int end = descriptor.indexOf(')', 1);
        String params = descriptor.substring(1, end);
        int idx = 0;
        while (idx < params.length()) {
            char ch = params.charAt(idx);
            if (ch == 'L') {
                int semi = params.indexOf(';', idx);
                if (semi < 0) throw new IllegalArgumentException("Invalid descriptor");
                idx = semi + 1;
            } else if (ch == '[') {
                do { idx++; } while (idx < params.length() && params.charAt(idx) == '[');
                if (idx >= params.length()) throw new IllegalArgumentException("Invalid descriptor");
                char inner = params.charAt(idx);
                if (inner == 'L') {
                    int semi = params.indexOf(';', idx);
                    if (semi < 0) throw new IllegalArgumentException("Invalid descriptor");
                    idx = semi + 1;
                } else {
                    idx++;
                }
            } else {
                idx++;
            }
            if (--pos < 0) throw new IllegalStateException("Stack underflow");
            stack[pos] = null;
        }
    } else {
        int idx = 0;
        while (idx < descriptor.length() && descriptor.charAt(idx) == '[') idx++;
        if (idx >= descriptor.length()) throw new IllegalArgumentException("Invalid descriptor");
        char ch = descriptor.charAt(idx);
        if (ch == 'L') {
            int semi = descriptor.indexOf(';', idx);
            if (semi < 0) throw new IllegalArgumentException("Invalid descriptor");
            idx = semi + 1;
        } else {
            idx++;
        }
        if (--pos < 0) throw new IllegalStateException("Stack underflow");
        stack[pos] = null;
    }
}

private void pop(final String descriptor){
    if (descriptor.length() == 0) return;
    int i = 0;
    if (descriptor.charAt(0) == '(') {          // method descriptor
        i = 1;
        while (descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == 'L') {                     // object type
                i = descriptor.indexOf(';', i) + 1;
            } else if (c == '[') {               // array type
                while (descriptor.charAt(i) == '[') i++;
                if (descriptor.charAt(i) == 'L') {
                    i = descriptor.indexOf(';', i) + 1;
                } else {
                    i++;                         // primitive array element
                }
            } else {                             // primitive type
                i++;
            }
            stack[--pos];                         // pop one abstract type
        }
    } else {                                     // single field descriptor
        char c = descriptor.charAt(i);
        if (c == 'L') {
            i = descriptor.indexOf(';', i) + 1;
        } else if (c == '[') {
            while (descriptor.charAt(i) == '[') i++;
            if (descriptor.charAt(i) == 'L') {
                i = descriptor.indexOf(';', i) + 1;
            } else {
                i++;
            }
        } else {
            i++;
        }
        stack[--pos];
    }
}

private void pop(final String descriptor){
    int count = 0;
    int start = 0;
    int end = descriptor.length();
    if (!descriptor.isEmpty() && descriptor.charAt(0) == '('){
        int close = descriptor.indexOf(')');
        if (close == -1){
            throw new IllegalArgumentException("Invalid method descriptor");
        }
        start = 1;
        end = close;
    }
    for (int i = start; i < end; ){
        char c = descriptor.charAt(i);
        if (c == '['){
            while (i < end && descriptor.charAt(i) == '['){
                i++;
            }
            if (i >= end) break;
            char base = descriptor.charAt(i);
            i++;
            if (base == 'L'){
                while (i < end && descriptor.charAt(i) != ';'){
                    i++;
                }
                if (i < end) i++; // skip terminating ';'
            }
            count++;
        }else if (c == 'L'){
            i++;
            while (i < end && descriptor.charAt(i) != ';'){
                i++;
            }
            if (i < end) i++; // skip terminating ';'
            count++;
        }else{
            // primitive type (single char)
            count++;
            i++;
        }
    }
    pos -= count;
}

private void pop(final String descriptor){
    int i = 0;
    if (!descriptor.isEmpty() && descriptor.charAt(0) == '('){
        i = 1;
        int end = descriptor.indexOf(')');
        while (i < end){
            char c = descriptor.charAt(i);
            int size = 1;
            if (c == 'J' || c == 'D'){
                size = 2;
                i++;
            }else if (c == '['){
                while (descriptor.charAt(i) == '['){
                    i++;
                }
                // arrays occupy 1 slot regardless of component type
                if (descriptor.charAt(i) == 'L'){
                    // consume object type
                    i = descriptor.indexOf(';', i) + 1;
                }else{
                    // primitive component
                    i++;
                }
                size = 1;
            }else if (c == 'L'){
                i = descriptor.indexOf(';', i) + 1;
            }else{
                i++;
            }
            pos -= size;
        }
    }else{
        while (i < descriptor.length()){
            char c = descriptor.charAt(i);
            int size = 1;
            if (c == 'J' || c == 'D'){
                size = 2;
                i++;
            }else if (c == '['){
                while (descriptor.charAt(i) == '['){
                    i++;
                }
                // arrays occupy 1 slot
                if (descriptor.charAt(i) == 'L'){
                    i = descriptor.indexOf(';', i) + 1;
                }else{
                    i++;
                }
                size = 1;
            }else if (c == 'L'){
                i = descriptor.indexOf(';', i) + 1;
            }else{
                i++;
            }
            pos -= size;
        }
    }
}

