        throw new IndexOutOfBoundsException();
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        int newCapacity = (buf.length << 1) > newCount ? (buf.length << 1) : newCount;
        buf = java.util.Arrays.copyOf(buf, newCapacity);
