public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    double minX = box.getMinX();
    double minY = box.getMinY();
    double width = box.getMaxX() - minX;
    double height = box.getMaxY() - minY;
    double halfWidth = width / 2.0;
    Box2D left = new Box2D(minX, minY, halfWidth, height);
    Box2D right = new Box2D(minX + halfWidth, minY, halfWidth, height);
    return new Pair<>(left, right);
}

