private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame.get(i);
        switch (type.getKind()) {
            case TOP:
                stackMapTableEntries.write((byte) 0);
                break;
            case INTEGER:
                stackMapTableEntries.write((byte) 1);
                break;
            case FLOAT:
                stackMapTableEntries.write((byte) 2);
                break;
            case DOUBLE:
                stackMapTableEntries.write((byte) 3);
                break;
            case LONG:
                stackMapTableEntries.write((byte) 4);
                break;
            case OBJECT:
                stackMapTableEntries.write((byte) 5);
                int objIdx = constantPool.addClassInfo(type.getDescriptor());
                stackMapTableEntries.write((byte) ((objIdx >> 8) & 0xFF));
                stackMapTableEntries.write((byte) (objIdx & 0xFF));
                break;
            case ARRAY:
                stackMapTableEntries.write((byte) 6);
                int arrIdx = constantPool.addClassInfo(type.getDescriptor());
                stackMapTableEntries.write((byte) ((arrIdx >> 8) & 0xFF));
                stackMapTableEntries.write((byte) (arrIdx & 0xFF));
                break;
            default:
                throw new IllegalArgumentException("Unsupported abstract type: " + type);
        }
    }
}

