@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure target type is Character or char
    if (!Character.class.isAssignableFrom(type) && type != char.class) {
        throw new IllegalArgumentException("Target type must be Character or char, but was: " + type);
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() == 1) {
            return s.charAt(0); // autoboxes to Character
        } else {
            throw new Exception("Cannot convert String to Character: \"" + s + "\" (length != 1)");
        }
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < Character.MIN_VALUE || intVal > Character.MAX_VALUE) {
            throw new Exception("Number value out of Character range: " + intVal);
        }
        return (char) intVal; // autoboxes to Character
    }
    if (value instanceof Boolean) {
        return ((Boolean) value) ? 't' : 'f';
    }
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    // Ensure the target type is Character (or primitive char); otherwise return as is
    if (!(Character.class.equals(type) || (type != null && type.isPrimitive() && type.getName().equals("char")))) {
        return value;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() == 1) {
            return s.charAt(0);
        }
        throw new IllegalArgumentException("String length must be 1 to convert to Character, got: " + s.length());
    }
    if (value instanceof Number) {
        return (char) ((Number) value).intValue();
    }
    if (value instanceof Boolean) {
        return (Boolean) value ? 't' : 'f';
    }
    throw new IllegalArgumentException("Cannot convert type " + value.getClass().getName() + " to Character");
}

