        return false;
    }
    // Build a set of lower‑case characters to search for
    Set<Character> searchSet = new HashSet<>();
    for (String s : searchStrArray) {
        if (s != null && !s.isEmpty()) {
            searchSet.add(Character.toLowerCase(s.charAt(0)));
        }
    }
    if (searchSet.isEmpty()) {
        return false;
    }
    // Inspect each character in the input string
    for (int i = 0; i < str.length(); i++) {
        char c = Character.toLowerCase(str.charAt(i));
        if (searchSet.contains(c)) {
            return true;
        }
    }
    return false;
}

