private static boolean isPrime(int num) {
    if (num <= 3) {
        return num > 1;
    }
    if (num % 2 == 0 || num % 3 == 0) {
        return false;
    }
    int i = 5;
    int w = 2;
    while (i * i <= num) {
        if (num % i == 0) {
            return false;
        }
        i += w;
        w = 6 - w;
    }
    return true;
}

