@Override public String readString() throws IOException {
    int length = 0;
    for (int i = 0; i < 4; i++) {
        int b = in.read();
        if (b == -1) {
            throw new EOFException("Unexpected end of stream while reading string length");
        }
        length = (length << 8) | (b & 0xFF);
    }
    byte[] bytes = new byte[length];
    int offset = 0;
    while (offset < length) {
        int read = in.read(bytes, offset, length - offset);
        if (read == -1) {
            throw new EOFException("Unexpected end of stream while reading string data");
        }
        offset += read;
    }
    return new String(bytes, "UTF-8");
}

