public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int i = 0;
    while (i < str.length()) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < str.length()) {
                char next = str.charAt(i + 1);
                // escaped backslash
                if (next == '\\') {
                    sb.append('\\');
                    i += 2;
                    continue;
                }
                // unicode escape \uXXXX
                if (next == 'u') {
                    if (i + 6 > str.length()) {
                        throw new Exception("Invalid unicode escape sequence at position " + i);
                    }
                    String hex = str.substring(i + 2, i + 6);
                    for (int h = 0; h < 4; h++) {
                        char ch = hex.charAt(h);
                        if (!Character.isDigit(ch) && !(ch >= 'a' && ch <= 'f') && !(ch >= 'A' && ch <= 'F')) {
                            throw new Exception("Invalid unicode escape sequence at position " + i);
                        }
                    }
                    sb.append((char) Integer.parseInt(hex, 16));
                    i += 6;
                    continue;
                }
                // standard single-character escapes
                switch (next) {
                    case 'n':
                        sb.append('\n');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'b':
                        sb.append('\b');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case '\"':
                        sb.append('\"');
                        break;
                    case '\'':
                        sb.append('\'');
                        break;
                    case '0':
                    case '1':
                    case '2':
                    case '3':
                    case '4':
                    case '5':
                    case '6':
                    case '7': {
                        // octal escape, up to 3 digits
                        int j = i + 1;
                        int octal = 0;
                        int count = 0;
                        while (j < str.length() && count < 3) {
                            char d = str.charAt(j);
                            if (d >= '0' && d <= '7') {
                                octal = (octal << 3) + (d - '0');
                                j++;
                                count++;
                            } else {
                                break;
                            }
                        }
                        sb.append((char) octal);
                        i = j;
                        continue;
                    }
                    default:
                        sb.append(next);
                }
                i += 2;
                continue;
            } else {
                // trailing backslash
                sb.append('\\');
                i++;
                continue;
            }
        } else {
            sb.append(c);
            i++;
        }
    }
    return sb.toString();
}

