protected int removeUnusedNodes() {
    int removed = 0;
    if (root == null) {
        return 0;
    }
    Deque<Category> stack = new ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Category node = stack.pop();
        List<Category> children = node.getChildren();
        if (children != null) {
            Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                if (!child.isActive()) {
                    it.remove();          // remove inactive node
                    removed++;             // count removed node
                } else {
                    stack.push(child);     // keep exploring active nodes
                }
            }
        }
    }
    return removed;
}

