}

protected int removeUnusedNodes(){
    int removedCount = 0;
    if (root == null) {
        return removedCount;
    }
    Deque<Category> nodeStack = new ArrayDeque<>();
    Deque<List<Category>> parentStack = new ArrayDeque<>();
    nodeStack.push(root);
    parentStack.push(null);
    while (!nodeStack.isEmpty()) {
        Category node = nodeStack.pop();
        List<Category> parentList = parentStack.pop();
        if (!node.isActive()) {
            if (parentList == null) {
                root = null;
            } else {
                parentList.remove(node);
            }
            removedCount++;
            continue;
        }
        List<Category> children = node.getChildren();
        if (children != null) {
            for (int i = children.size() - 1; i >= 0; i--) {
                nodeStack.push(children.get(i));
                parentStack.push(children);
            }
        }
    }
    return removedCount;
}

