    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // If the start node already satisfies the predicate or is the stop node,
    // we can immediately return a circulator pointing to it.
    if (start != null && (predicate.test(start) || start == stop)) {
        return new OuterFaceCirculator(start, dir);
    }
    // Create a circulator that will traverse the outer face starting from 'start'.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // Traverse until we find a node satisfying the predicate or hit the stop node.
    Node current = start;
    while (true) {
        current = circ.next(); // advance to the next node in the specified direction
        if (current == stop || predicate.test(current)) {
            return new OuterFaceCirculator(current, dir);
        }
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start);
    while (true) {
        Node current = circ.get();
        if (predicate.test(current)) {
            return circ;
        }
        if (current == stop) {
            return circ;
        }
        circ.next(dir);
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    Node current = circulator.node();
    while (!current.equals(stop) && !predicate.test(current)){
        circulator.next();
        current = circulator.node();
    }
    return circulator;
}

