    } else if (b >= 'A' && b <= 'F') {
        return (byte) (b - 'A' + 10);
    } else if (b >= 'a' && b <= 'f') {
        return (byte) (b - 'a' + 10);
    } else {
        // If not a valid hex digit, return -1 (0xFF)
        return -1;
    }
}

