protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty() || graph == null) {
        return null;
    }
    List<E> edgeList = new ArrayList<>(tour);
    // Assume the tour is non-empty, pick the first edge to determine start and end vertices
    E firstEdge = edgeList.get(0);
    V startVertex = graph.getEdgeSource(firstEdge);
    V endVertex = graph.getEdgeTarget(firstEdge);
    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }
    return new GraphWalk<>(graph, startVertex, endVertex, edgeList, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty())
        return null;
    Set<E> remaining = new HashSet<>(tour);
    List<E> orderedEdges = new ArrayList<>(tour.size());

    // Pick an arbitrary starting edge
    E currentEdge = remaining.iterator().next();
    remaining.remove(currentEdge);
    orderedEdges.add(currentEdge);

    // Determine the starting vertex (arbitrary choice of source)
    V currentVertex = graph.getEdgeSource(currentEdge);
    // Determine the next vertex after the starting edge
    V nextVertex = graph.getEdgeTarget(currentEdge).equals(currentVertex)
                   ? graph.getEdgeSource(currentEdge)
                   : graph.getEdgeTarget(currentEdge);

    // Build the rest of the tour by following connected edges
    while (!remaining.isEmpty()){
        boolean found = false;
        for (E e : remaining){
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(nextVertex) || tgt.equals(nextVertex)){
                orderedEdges.add(e);
                remaining.remove(e);
                // advance to the other vertex of the chosen edge
                nextVertex = src.equals(nextVertex) ? tgt : src;
                found = true;
                break;
            }
        }
        if (!found)
            // If we cannot continue, the set does not form a proper tour
            return null;
    }

    // Create the list of vertices in order
    List<V> vertexList = new ArrayList<>(orderedEdges.size() + 1);
    vertexList.add(currentVertex);
    for (E e : orderedEdges){
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        V newVertex = src.equals(currentVertex) ? tgt : src;
        vertexList.add(newVertex);
        currentVertex = newVertex;
    }

    // Compute total weight
    double weight = 0.0;
    for (E e : orderedEdges){
        weight += graph.getEdgeWeight(e);
    }

    // Construct and return a GraphPath implementation
    // (Assuming a GraphPathImpl constructor with these parameters exists)
    return new GraphPathImpl<>(graph, vertexList.get(0), vertexList.get(vertexList.size() - 1),
                               vertexList, orderedEdges, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    return new SimpleGraphPath<V,E>(graph, new java.util.ArrayList<E>(tour));
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()) {
        return new GraphPath<>();
    }
    List<E> orderedEdges = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);
    // start with an arbitrary edge
    Iterator<E> it = remaining.iterator();
    E startEdge = it.next();
    remaining.remove(startEdge);
    orderedEdges.add(startEdge);
    V current = graph.getEdgeTarget(startEdge);
    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> iter = remaining.iterator();
        while (iter.hasNext()) {
            E e = iter.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current)) {
                orderedEdges.add(e);
                current = tgt;
                iter.remove();
                found = true;
                break;
            }
        }
        if (!found) {
            break; // cannot continue constructing a linear path
        }
    }
    GraphPath<V,E> path = new GraphPath<>();
    for (E e : orderedEdges) {
        path.addEdge(e);
    }
    return path;
}

