private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list.isEmpty()) {
        return;
    }
    synchronized (this) {
        synchronized (list) {
            ListNode<E> node = list.getHead();
            while (node != null) {
                ListNode<E> next = node.getNext();
                list.removeListNode(node);
                this.addListNode(node);
                node = next;
            }
        }
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list.isEmpty() || list == this) {
        return;
    }
    // Detach the source list's nodes and append them to the destination list.
    if (this.isEmpty()) {
        // Destination list is empty; simply adopt the source list's nodes.
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Link the two lists together.
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }
    // Update the element count.
    this.size += list.size;
    // Clear the source list.
    list.head = null;
    list.tail = null;
    list.size = 0;
}

