    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    ListNodeImpl<E> srcFirst = list.head;
    if (srcFirst == null) return;
    ListNodeImpl<E> srcLast = list.tail;

    if (this.head == null){
        this.head = srcFirst;
        this.tail = srcLast;
    } else {
        this.tail.next = srcFirst;
        srcFirst.prev = this.tail;
        this.tail = srcLast;
    }

    this.size += list.size;
    list.head = null;
    list.tail = null;
    list.size = 0;
}

