public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null || !file.exists()) {
        return result;
    }
    BufferedReader reader = new BufferedReader(new FileReader(file));
    String line;
    while ((line = reader.readLine()) != null) {
        line = line.trim();
        if (line.isEmpty()) {
            continue;
        }
        String[] parts = line.split("\\|", 2);
        if (parts.length < 2) {
            continue;
        }
        long ts;
        try {
            ts = Long.parseLong(parts[0].trim());
        } catch (NumberFormatException e) {
            continue;
        }
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            // Assume the range has getStartMillis() and getEndMillis() methods
            if (ts >= range.getStartMillis() && ts <= range.getEndMillis()) {
                result.add(new ThreadSnapshot(ts, parts[1]));
                break;
            }
        }
    }
    reader.close();
    return result;
}

